mapper.select:
select korean_card_id
from korean_cards kc
where
    exists (
        select 1
        from foreign_cards fc
        where fc.language_code = #{code} and fc.korean_card_id = kc.korean_card_id
    ) and kc.level = #{level}
order by korean_word
    LIMIT #{limit} OFFSET #{offset}
;

select count(kc.korean_card_id)
from korean_cards kc
where
    exists (
        select 1
        from foreign_cards fc
        where fc.language_code = #{code} and fc.korean_card_id = kc.korean_card_id
    ) and kc.level = #{level}
;
